                                        src="https://www.macitynet.it/wp-content/uploads/2026/07/facetime-truffa-2-741x486.jpg" srcset="https://www.macitynet.it/wp-content/uploads/2026/07/facetime-truffa-2-741x486.jpg 741w, https://www.macitynet.it/wp-content/uploads/2026/07/facetime-truffa-2-50x34.jpg 50w" sizes="(max-width: 741px) 100vw, 741px" 
